let adminStep8State,adminStep8Tab='clients';
admin=async function(){if(me?.role!=='admin')return;$('#view').innerHTML=page('Application administration.','Manage supermarket access and review account activity.')+'<div class="panel">Loading clients...</div>';try{const [clients,summary,audit]=await Promise.all([api('/admin/clients'),api('/admin/overview'),api('/admin/audit')]);if(view!=='admin'||me?.role!=='admin')return;adminStep8State={clients,summary,audit};$('#view').innerHTML=page('Application administration.','Manage supermarket accounts. Connection indicators describe this server; official configuration does not prove provider availability.','<button class="btn secondary" id="admin-refresh">Refresh</button>')+`<div class="stats">${[['Supermarkets',summary.total],['Access enabled',summary.enabled],['Access disabled',summary.disabled],['QR connected',summary.linkedDevices]].map(([label,n])=>`<div class="stat"><div class="stat-label">${label}</div><div class="value">${n}</div></div>`).join('')}</div><div class="mode-tabs"><button id="admin-clients-tab">Clients</button><button id="admin-audit-tab">Access history</button></div><div id="admin-content"></div>`;$('#admin-refresh').onclick=admin;$('#admin-clients-tab').onclick=()=>{adminStep8Tab='clients';adminStep8Content()};$('#admin-audit-tab').onclick=()=>{adminStep8Tab='audit';adminStep8Content()};adminStep8Content()}catch(e){$('#view').innerHTML=page('Application administration.','Could not load accounts')+'<div class="note warning">'+esc(e.message)+'</div>'}};
function adminAuditTable(audit){return table(['TIME','ADMINISTRATOR','CLIENT','CHANGE','REASON'],audit.map(a=>row([date(a.created_at),esc(a.actor_email),esc(a.client_email),esc(a.previous_enabled?'Enabled':'Disabled')+' → '+esc(a.enabled?'Enabled':'Disabled'),esc(a.reason)])))}
function adminStep8Content(){if(adminStep8Tab==='audit'){$('#admin-content').innerHTML='<div class="panel"><h3>Latest 200 access changes</h3>'+adminAuditTable(adminStep8State.audit)+'</div>';return}$('#admin-content').innerHTML='<div class="panel"><div class="toolbar"><input id="admin-search" placeholder="Search store, email or store ID" aria-label="Search clients"><select id="admin-filter" aria-label="Filter access"><option value="all">All clients</option><option value="enabled">Enabled</option><option value="disabled">Disabled</option></select></div><div id="admin-rows"></div></div>';$('#admin-search').oninput=adminStep8Rows;$('#admin-filter').onchange=adminStep8Rows;adminStep8Rows()}
function adminStep8Rows(){const q=$('#admin-search').value.toLowerCase(),filter=$('#admin-filter').value,list=adminStep8State.clients.filter(c=>[c.name,c.email,c.id].join(' ').toLowerCase().includes(q)&&(filter==='all'||c.enabled===(filter==='enabled')));$('#admin-rows').innerHTML=list.length?table(['SUPERMARKET','OWNER','ACCESS','WHATSAPP','USAGE','LAST SIGN-IN',''],list.map(c=>row([`<b>${esc(c.name)}</b><small>${esc(c.id)}</small>`,esc(c.email)+'<small>Registered '+date(c.created)+'</small>',pill(c.enabled?'Enabled':'Disabled'),esc(c.webStatus)+'<small>Official: '+(c.officialConfigured?'configured':'not configured')+'</small>',`${c.products} products / ${c.customers} customers / ${c.orders} orders`,c.lastLogin?date(c.lastLogin):'Not recorded',`<button class="btn small secondary" data-admin-detail="${esc(c.id)}">Details</button> <button class="btn small ${c.enabled?'danger':'secondary'}" data-admin-access="${esc(c.id)}">${c.enabled?'Disable':'Enable'} access</button>`]))):'<p>No matching supermarket accounts.</p>';$$('[data-admin-access]').forEach(b=>b.onclick=()=>adminStep8Access(b.dataset.adminAccess));$$('[data-admin-detail]').forEach(b=>b.onclick=()=>adminStep8Detail(b.dataset.adminDetail))}
async function adminStep8Detail(id){try{const c=await api('/admin/clients/'+encodeURIComponent(id));modal(`<h2>${esc(c.name)}</h2><p>${esc(c.email)}<br>Store ID: ${esc(c.id)}</p><div class="note">${esc(c.enabled?'Access enabled':'Access disabled')}<br>Store phone: ${esc(c.store.phone||'Not set')}<br>Address: ${esc(c.store.address||'Not set')}<br>Timezone: ${esc(c.store.timezone||'Not set')}<br>Active orders: ${c.activeOrders}<br>Ordering assistant: ${c.automations.orderAssistant?'enabled':'disabled'}<br>Notifications: ${c.automations.notifications?'enabled':'disabled'}</div><h3>Access history</h3>${adminAuditTable(c.audit)}`)}catch(e){toast(e.message)}}
function adminStep8Access(id){const c=adminStep8State.clients.find(c=>c.id===id);modal(`<h2>${c.enabled?'Disable':'Enable'} client access</h2><p><b>${esc(c.name)}</b><br>${esc(c.email)}</p><div class="note warning">${c.enabled?'Disabling signs out all dashboard sessions and stops this server’s linked-device connection. Queued sends check access before dispatch. Messages already submitted cannot be recalled. Existing payment webhooks can still reconcile money received.':'The owner can sign in again. Previous sessions stay signed out. Review schedules and notification settings before reconnecting WhatsApp.'}</div><form id="edit-form"><label>Reason<textarea name="reason" required maxlength="500" placeholder="Why is access changing?"></textarea></label>${formEnd(c.enabled?'Disable access':'Enable access')}`);bindForm(async b=>{await api('/admin/access','POST',{id:c.id,enabled:!c.enabled,expectedEnabled:c.enabled,reason:b.reason});await admin();toast('Client access updated')})}
